<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\FilmActor;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class FilmActorStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\FilmActorModel',
  1 => 'App\\Controllers\\FilmActorController',
  2 => 'App\\Validation\\FilmActorRules',
  3 => 'App\\Entities\\FilmActorEntity',
  4 => 'App\\Services\\FilmActorService',
  5 => 'App\\Controllers\\Api\\V1\\FilmActorApiController',
  6 => 'App\\API\\Resources\\FilmActorResource',
  7 => 'App\\Validation\\FilmActorApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
